// Wraps the OpenNext worker so shared code finds the database: @polyradar/db
// reads DATABASE_URL, which here comes from the Hyperdrive binding.
// @ts-ignore generated by `opennextjs-cloudflare build`
import handler from './.open-next/worker.js';

interface Env { HYPERDRIVE: { connectionString: string } }

export default {
  async fetch(req: Request, env: Env, ctx: unknown) {
    process.env.DATABASE_URL = env.HYPERDRIVE.connectionString;
    return handler.fetch(req, env, ctx);
  },
};
